/**
 * @file src/lib/combatEntryTickets.ts
 * Shared combat entry tickets for Battle Tower and Battle Subway.
 */

import type { GameRuntime } from '../types/game.js';
import { BALANCE } from '../../constants/balance/balance.ts';

export function getCombatEntryTicketCost(): number {
  return Math.max(1, Math.floor(Number(BALANCE?.COMBAT_ENTRY_TICKET_COST) || 1));
}

function resolveSafeTicketCost(cost: unknown): number {
  const numCost = Number(cost);
  if (!Number.isFinite(numCost) || numCost < 0) {
    return getCombatEntryTicketCost();
  }
  return Math.floor(numCost);
}

export function canAffordCombatEntryTicket(
  game: GameRuntime | null | undefined,
  cost: number = getCombatEntryTicketCost(),
): boolean {
  if (!game || typeof game !== 'object') return false;
  const required = resolveSafeTicketCost(cost);
  if (required <= 0) return true;
  return Math.floor(Number(game.combatTickets) || 0) >= required;
}

/** Consumes entry tickets; returns false if insufficient or invalid game. */
export function tryConsumeCombatEntryTicket(
  game: GameRuntime | null | undefined,
  cost: number = getCombatEntryTicketCost(),
): boolean {
  if (!game || typeof game !== 'object') return false;
  const required = resolveSafeTicketCost(cost);
  const have = Math.floor(Number(game.combatTickets) || 0);
  if (required <= 0) return true;
  if (have < required) return false;
  game.combatTickets = have - required;
  return true;
}
